  "explain": "📖 교재 근거 (L2993):\n#### 제모제 🎯 기출 (치오글라이콜릭애씨드 함유 제품에만 표시함) — 사용금지: ① 생리 전후·산전·산후·병후 ② 얼굴·상처·부스럼·습진·짓무름·염증·반점·자극 피부 ③ 유사 제품 부작용 피부 ④ 약한 피부·남성 수염 부위\n해설: 건강한 팔·다리의 털이 있는 부위는 제모제 사용금지 대상이 아니다. 제모제는 해당 부위에 정상적으로 사용하는 제품이다.",
