  "citation": "📖 출처: 과목2 문제은행 Q209",
  "stem": "알파-하이드록시애씨드(AHA) 함유 제품(0.5% 이하 제품 제외)의 표시 주의사항이 아닌 것을 모두 고른 것은?",
